function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function area(){if(points.length<3)return 0;const lat=points.reduce((a,p)=>a+p[0],0)/points.length;const xy=points.map(p=>[p[1]*111320*Math.cos(lat*Math.PI/180),p[0]*111320]);return Math.abs(xy.reduce((s,p,i)=>{const q=xy[(i+1)%xy.length];return s+p[0]*q[1]-q[0]*p[1]},0)/2)*10.7639}
function side(){if(step===0){$('#side-content').innerHTML=`<button id="generate" class="primary" ${!closed?'disabled':''}>Generate housing plan <span>↗</span></button>`;$('#generate').onclick=generate}else if(step===1){$('#side-content').innerHTML=`<div class="side-profile"><div class="profile-swatch">⌂</div><div><strong>The Fast-Set Box</strong><small>Out of the Box Housing</small></div></div><a class="source-link" href="${sourceLinks.manufacturer}" target="_blank" rel="noopener">View manufacturer specifications ↗</a><div class="metric-line"><span>Published footprint</span><strong>19 × 8 ft</strong></div><div class="metric-line"><span>Prepared concept</span><strong>12 units</strong></div><div class="readiness"><strong>A concept to explore</strong>Placement and access are illustrative. Zoning, fire access and utility capacity need professional review.</div><button id="next" class="primary">Prepare your next steps <span>↗</span></button><p class="side-note">Model height and exterior details are illustrative. This demo does not calculate site feasibility.</p>`;$('#next').onclick=()=>setStep(2)}else{$('#side-content').innerHTML=`<div class="side-label">READY FOR A CONVERSATION</div><div class="address">A vision you can share.<small>A scope experts can review.</small></div><p class="side-note">Download the concept presentation and an expert discussion brief. Every document keeps assumptions and open questions visible.</p><div class="readiness"><strong>Human review comes next</strong>Drafts require leadership review and board sign-off before external release.</div><button id="back-concept" class="primary">Return to your concept <span>↗</span></button>`;$('#back-concept').onclick=()=>setStep(1)}}
function updateBoundary(){
 closed=points.length>=3;
 if(polygon){map.removeLayer(polygon);polygon=null}if(line){map.removeLayer(line);line=null}
 if(closed)polygon=L.polygon(points,{color:'#d8ffc4',weight:3,fillColor:'#b9efac',fillOpacity:.2,interactive:false}).addTo(map);
 else if(points.length>1)line=L.polyline(points,{color:'#d8ffc4',weight:3,interactive:false}).addTo(map);
 const button=$('#generate');if(button)button.disabled=!closed||busy;
 $('#undo').disabled=$('#clear').disabled=points.length===0;
}
function redraw(){
 markers.forEach(m=>map.removeLayer(m));
 markers=points.map((p,i)=>{
  const marker=L.marker(p,{draggable:true,bubblingMouseEvents:false,title:`Drag boundary point ${i+1}`,icon:L.divIcon({className:'boundary-point',html:'',iconSize:[18,18],iconAnchor:[9,9]})}).addTo(map);
  marker.on('drag',()=>{const p=marker.getLatLng();points[i]=[p.lat,p.lng];updateBoundary()});
  marker.on('click',e=>L.DomEvent.stopPropagation(e.originalEvent));
  return marker;
 });
 updateBoundary();
}
function initMap(){if(!window.L){$('#map-error').hidden=false;toast('Map library could not load. Reconnect and refresh.');return}map=L.map('map',{zoomControl:false,doubleClickZoom:false}).setView([33.90353,-118.01655],18);L.control.zoom({position:'topright'}).addTo(map);const tiles=L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',{attribution:'Tiles © Esri · Maxar · Earthstar Geographics',maxZoom:20,crossOrigin:true}).addTo(map);let loaded=false;tiles.on('tileload',()=>{loaded=true;$('#map-error').hidden=true});tiles.on('tileerror',()=>{if(!loaded)$('#map-error').hidden=false});map.on('click',e=>{if(step||busy)return;points.push([e.latlng.lat,e.latlng.lng]);redraw()});map.getContainer().style.cursor='crosshair';const mapResizeObserver=new ResizeObserver(()=>{if(!$('#map').hidden)map.invalidateSize()});mapResizeObserver.observe($('#map'))}
$('#undo').onclick=()=>{points.pop();redraw()};$('#clear').onclick=()=>{points=[];redraw()};function loadSampleBoundary(){points=preset.map(p=>[...p]);closed=true;redraw();map.fitBounds(points,{padding:[100,100]});toast('Sample boundary loaded. Illustrative location; select your preferred lot for recording.')};
async function generate(){if(!closed||busy)return;busy=true;$('#loading').hidden=false;$('#generate').disabled=true;threeModule??=import('./scene.js?v=no-aisle-7');try{const mod=await threeModule;await new Promise(r=>setTimeout(r,1300));$('#loading-copy').textContent='Placing the prepared Fast-Set Box concept';if(sceneController)sceneController.dispose();$('#three-view').hidden=false;sceneController=await mod.createScene($('#three-view'),points);await new Promise(r=>setTimeout(r,900));setStep(1)}catch(e){console.error(e);toast('The 3D view could not load. Check your connection and try again.');$('#three-view').hidden=true;$('#generate').disabled=false}finally{$('#loading').hidden=true;busy=false}}
function setStep(n){if(n>0&&!sceneController)return;step=n;$('.workspace').classList.toggle('delivery',n===2);$('#map').hidden=n!==0;$('#three-view').hidden=n===0;$('#map-toolbar').hidden=n!==0;$('#scene-toolbar').hidden=n!==1;$('#scene-label').hidden=n===0;$('#legend').hidden=n!==1;$('#results').hidden=n!==1;$('#deliverables').hidden=n!==2;document.querySelectorAll('.step').forEach((b,i)=>{b.classList.toggle('active',i===n);b.disabled=i>0&&!sceneController;b.onclick=()=>setStep(i)});side();if(n===0)requestAnimationFrame(()=>map.invalidateSize());if(n===2)renderDeliverables();setTimeout(()=>sceneController?.resize(),40)}
$('#orbit').onclick=()=>{const active=sceneController?.toggleOrbit();$('#orbit').classList.toggle('selected',active)};$('#top').onclick=()=>{sceneController?.top();$('#orbit').classList.remove('selected')};$('#perspective').onclick=()=>sceneController?.perspective();$('#capture').onclick=()=>{const a=document.createElement('a');a.download='homemore-concept.png';a.href=sceneController.capture();a.click();toast('Concept image downloaded')};
$('#results').innerHTML=`<div class="result"><label>Prepared concept</label><strong>12 <span style="font-size:15px;letter-spacing:0">homes</span></strong><small>Illustrative count, not site yield</small></div><div class="result"><label>Each Fast-Set Box</label><strong>152 <span style="font-size:15px;letter-spacing:0">ft²</span></strong><small>Manufacturer-published footprint</small></div><div class="result"><label>Professional review</label><strong>Required</strong><small>Zoning · utilities · life safety</small></div>`;
function renderDeliverables(){$('#deliverables').innerHTML=`<div class="delivery-head"><div><h3>Turn a possibility into a conversation.</h3><p>Prepared drafts for your board and your professional team.</p></div></div><div class="delivery-grid"><article class="delivery-card"><span class="file-icon">PRESENTATION</span><h4>The board conversation</h4><p>A concise slide presentation with the site concept, housing profile, planning assumptions and next steps.</p><button id="export-slides">↓ Export slide presentation</button></article><article class="delivery-card"><span class="file-icon">EXPERT BRIEF</span><h4>The professional starting point</h4><p>A discussion brief for land-use counsel, civil engineering and architectural review.</p><button id="export-brief">↓ Download discussion brief</button></article></div><section class="contacts"><h3>People who help make it real.</h3><p>Verified starting points and professional directories. No partnership or project approval is implied.</p>${[['Campus coordination','Biola Facilities Management','Site access, campus operations and utility records.',sourceLinks.facilities,'Contact facilities'],['Planning review','City of La Mirada','Ask about the proposed use, campus approvals and application pathway.',sourceLinks.planning,'Planning department'],['Land-use counsel','California certified referral services','Request an attorney experienced in land use and affordable housing.',sourceLinks.lawyer,'Find a referral'],['Civil engineering','California professional license lookup','Verify a prospective civil engineer before engagement.',sourceLinks.engineer,'Verify an engineer'],['Architectural review','California Architects Board','Verify an architect for accessibility and building-code review.',sourceLinks.architect,'Verify an architect']].map(c=>`<div class="contact"><div><span class="eyebrow">${c[0]}</span><p><strong>${c[1]}</strong></p><p>${c[2]}</p></div><a target="_blank" rel="noopener" href="${c[3]}">${c[4]} ↗</a></div>`).join('')}</section>`;$('#export-slides').onclick=exportSlides;$('#export-brief').onclick=exportBrief}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportSlides(){const picture=sceneController.capture();const slides=[['Homemore','An illustrative housing concept at Biola University.<br>A starting point for a church leadership conversation.'],['A place to begin','12 Fast-Set Boxes in a prepared site concept.<br>The selected boundary anchors the illustration. This demo does not calculate feasibility.'],['The Fast-Set Box','Published footprint: 19 × 8 feet, or 152 square feet.<br>Out of the Box Housing. Configuration and specifications require confirmation.'],['Questions before commitments','Confirm the permitted use and campus approvals.<br>Review fire access, accessibility and foundations.<br>Assess utilities, parking and an operating partner.'],['A professional next step','Share the concept with campus facilities and La Mirada planning staff.<br>Engage land-use counsel, a civil engineer and an architect.<br>Seek leadership review before external release.']];download('homemore-presentation.html',`<!doctype html><html><head><meta charset="utf-8"><title>Homemore — Board Presentation</title><style>body{margin:0;background:#f1f5ef;font-family:Arial,sans-serif;color:#173e35}section{box-sizing:border-box;min-height:100vh;padding:7vw;display:flex;flex-direction:column;justify-content:center;position:relative;page-break-after:always}h1{font-size:5vw;line-height:1.1;margin:0 0 3vw;max-width:900px}p{font-size:2vw;line-height:1.7;max-width:1000px}small{font-size:11px;position:absolute;bottom:30px;left:7vw;right:7vw;line-height:1.5}img{max-height:58vh;max-width:85vw;object-fit:contain;border-radius:8px}a{color:inherit}nav{position:fixed;right:20px;top:15px;z-index:2;font-size:12px;background:white;padding:10px;border-radius:5px}@media print{nav{display:none}section{height:190mm;min-height:0}h1{font-size:40pt}p{font-size:20pt}img{max-height:130mm}@page{size:A4 landscape;margin:0}}</style></head><body><nav>Use ↓ / ↑ to navigate · Print to save PDF</nav>${slides.map((s,i)=>`<section><div style="font-size:12px;letter-spacing:3px;margin-bottom:30px">HOMEMORE · ${String(i+1).padStart(2,'0')}</div><h1>${s[0]}</h1>${i===1?`<img src="${picture}" alt="Illustrative housing concept">`:''}<p>${s[1]}</p>${i===2?`<a href="${sourceLinks.manufacturer}">Manufacturer source</a>`:''}<small>ILLUSTRATIVE DEMO. DRAFT — HUMAN REVIEW AND BOARD SIGN-OFF REQUIRED.<br>${disclaimer}</small></section>`).join('')}<script>document.addEventListener('keydown',e=>{if(['ArrowRight','ArrowDown','PageDown',' '].includes(e.key)){e.preventDefault();window.scrollBy({top:innerHeight,behavior:'smooth'})}if(['ArrowLeft','ArrowUp','PageUp'].includes(e.key)){e.preventDefault();window.scrollBy({top:-innerHeight,behavior:'smooth'})}})<\/script></body></html>`,'text/html');toast('Slide presentation downloaded. Open in a browser to present or save as PDF.')}
function exportBrief(){download('homemore-expert-discussion-brief.txt',`HOMEMORE\nEXPERT DISCUSSION BRIEF\n\nILLUSTRATIVE DEMO — DRAFT FOR HUMAN REVIEW\n${disclaimer}\n\nSITE\nBiola University, 13800 Biola Avenue, La Mirada, CA.\nUser-drawn study area: approximately ${Math.round(area()).toLocaleString()} square feet. Not a surveyed parcel.\n\nPREPARED CONCEPT\n12 Fast-Set Boxes. Published unit footprint: 19 x 8 feet / 152 square feet.\nThis prepared count is not calculated from the selected boundary. Model height and appearance are illustrative.\nParking displaced, utility capacity, occupancy and project cost: not established.\n\nLAND-USE COUNSEL\nConfirm ownership, proposed-use classification, campus approvals, local zoning, and applicable state pathways. Do not assume SB 4 authorizes this concept.\n\nCIVIL ENGINEER\nReview survey, grading, drainage, foundations, water and sewer capacity, electrical service, hydrant coverage and emergency access including turning geometry.\n\nARCHITECT\nReview unit configuration, building classification, accessibility, accessible routes, separation and life safety.\n\nOPERATIONS\nIdentify a qualified housing operator, service model, resident eligibility, staffing and a sustainable operating budget. No operating partner is committed.\n\nSTARTING POINTS\nBiola facilities: ${sourceLinks.facilities}\nLa Mirada planning: ${sourceLinks.planning}\nLand-use attorney referral: ${sourceLinks.lawyer}\nCivil engineer license verification: ${sourceLinks.engineer}\nArchitect license verification: ${sourceLinks.architect}\nManufacturer footprint: ${sourceLinks.manufacturer}\n\nLeadership review and board sign-off are required before external release.\n`,'text/plain');toast('Expert discussion brief downloaded')}
initMap();side();if(map)updateBoundary();
if(document.modelContext?.registerTool){for(const tool of [{name:'load_sample_boundary',description:'Load the illustrative sample boundary in the demo map.',execute:()=>{loadSampleBoundary();return {boundaryReady:closed}}},{name:'generate_prepared_concept',description:'Reveal the prepared 12-unit illustrative concept after at least three boundary points are set.',execute:async()=>{if(!closed)throw new Error('Add at least three boundary points first');await generate();return {stage:step,illustrative:true}}}]){try{Promise.resolve(document.modelContext.registerTool({...tool,inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false}})).catch(()=>{})}catch{}}}



